import json, hashlib, subprocess, sys, os
repo, up = sys.argv[1], sys.argv[2]
rev = '53a79413c58678b1c50dde57e71de5c123132716'
lock = json.load(open(os.path.join(repo, 'vendor/tcg-engines/upstream.lock.json')))
assert lock['revision'] == rev
p = subprocess.Popen(['git', '-C', up, 'cat-file', '--batch'], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
def blob(path):
    p.stdin.write(f'{rev}:{path}\n'.encode()); p.stdin.flush()
    header = p.stdout.readline().split()
    if header[-1] == b'missing': raise SystemExit('missing upstream ' + path)
    size = int(header[2]); data = p.stdout.read(size); p.stdout.read(1)
    return header[0].decode(), data
patched = {x['path'] for x in lock['patches']}
same = diff = 0
for row in lock['files']:
    oid, data = blob(row['upstream_path'])
    assert oid == row['git_blob'], row['path']
    assert hashlib.sha256(data).hexdigest() == row['upstream_sha256'], row['path']
    local = open(os.path.join(repo, 'vendor/tcg-engines', row['path']), 'rb').read()
    if row['path'] in patched:
        diff += 1; assert local != data
    else:
        assert local == data, row['path']; same += 1
for lic in lock['licenses']:
    oid, data = blob(lic['upstream_path'])
    assert data == open(os.path.join(repo, 'vendor/tcg-engines', lic['path']), 'rb').read(), lic['path']
for pt in lock['patches']:
    orig = open(os.path.join(repo, 'vendor/tcg-engines', pt['original_path']), 'rb').read()
    oid, data = blob(pt['path'].removeprefix('upstream/'))
    assert orig == data, pt['id']
# every file present on disk under upstream/ is in the lock
listed = {r['path'] for r in lock['files']}
disk = set()
for d, _, fs in os.walk(os.path.join(repo, 'vendor/tcg-engines/upstream')):
    for f in fs: disk.add(os.path.relpath(os.path.join(d, f), os.path.join(repo, 'vendor/tcg-engines')))
assert disk == listed, (disk ^ listed)
scopes = {}
for r in lock['files']: scopes[r['scope']] = scopes.get(r['scope'], 0) + 1
print(f'PASS independent git cat-file check: {len(lock["files"])} files ({same} identical, {diff} patched), scopes {scopes}, {len(lock["licenses"])} licenses, {len(lock["patches"])} patch originals, tests {len(lock["tests"])}, runtime externals {lock["runtime_externals"]}')
